/* Local palette tracing: true SVG paths, no embedded raster or external service. */
export function tracePalette(data,width,height,levels=4){levels=Math.max(2,Math.min(8,Math.round(levels)));const groups=new Map(),step=255/(levels-1),colorAt=(x,y)=>{const i=(y*width+x)*4;if(data[i+3]<96)return null;return '#'+[0,1,2].map(k=>Math.round(Math.round(data[i+k]/step)*step).toString(16).padStart(2,'0')).join('')};for(let y=0;y<height;y++){let x=0;while(x<width){const color=colorAt(x,y),start=x++;while(x<width&&colorAt(x,y)===color)x++;if(color){if(!groups.has(color))groups.set(color,[]);groups.get(color).push(`M${start} ${y}h${x-start}v1H${start}z`)}}}return `<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}" viewBox="0 0 ${width} ${height}">${[...groups].map(([fill,paths])=>`<path fill="${fill}" d="${paths.join('')}"/>`).join('')}</svg>`}
